from collections import OrderedDict

def cache_sim(capacity, ttl, ops):
    store = {}  # key -> (value, write_time)
    order = OrderedDict()  # key -> None, maintains LRU order (least recently used first)
    results = []

    def remove_key(key):
        if key in store:
            del store[key]
        if key in order:
            del order[key]

    for op in ops:
        kind = op[0]
        t = op[1]
        if kind == 'put':
            key = op[2]
            value = op[3]
            # check existing entry
            if key in store:
                val, wt = store[key]
                if t >= wt + ttl:
                    # expired, treat as absent
                    remove_key(key)
                else:
                    # update value, write time, move to end (most recently used)
                    store[key] = (value, t)
                    order.pop(key, None)
                    order[key] = None
                    continue
            # key is absent now (either never existed or expired and removed)
            if key not in store:
                if len(store) >= capacity:
                    # evict LRU
                    if order:
                        lru_key, _ = order.popitem(last=False)
                        if lru_key in store:
                            del store[lru_key]
                store[key] = (value, t)
                order.pop(key, None)
                order[key] = None
        elif kind == 'get':
            key = op[2]
            if key in store:
                val, wt = store[key]
                if t >= wt + ttl:
                    # expired
                    remove_key(key)
                    results.append(-1)
                else:
                    results.append(val)
                    order.pop(key, None)
                    order[key] = None
            else:
                results.append(-1)
    return results

